// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// UploadFile Keep a file, sent as it is; a task names it by the id answered
	// (POST /files)
	UploadFile(ctx context.Context, request UploadFileRequestObject) (UploadFileResponseObject, error)
	// ProjectTags Every tag in use in a workspace (all when left out)
	// (GET /project-tags)
	ProjectTags(ctx context.Context, request ProjectTagsRequestObject) (ProjectTagsResponseObject, error)
	// Projects A page of the projects that match, filtered and sorted by the server
	// (GET /projects)
	Projects(ctx context.Context, request ProjectsRequestObject) (ProjectsResponseObject, error)
	// CreateProject Make a project
	// (POST /projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// DeleteProject Delete a project
	// (DELETE /projects/{id})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)
	// Project One project
	// (GET /projects/{id})
	Project(ctx context.Context, request ProjectRequestObject) (ProjectResponseObject, error)
	// UpdateProject Change a project
	// (PATCH /projects/{id})
	UpdateProject(ctx context.Context, request UpdateProjectRequestObject) (UpdateProjectResponseObject, error)
	// Search The records that match a few letters, best first
	// (GET /search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// SignOut Sign out
	// (DELETE /session)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
	// Me Who is signed in (401 when nobody is)
	// (GET /session)
	Me(ctx context.Context, request MeRequestObject) (MeResponseObject, error)
	// SignIn Sign in; the server sets the session cookie (httpOnly)
	// (POST /session)
	SignIn(ctx context.Context, request SignInRequestObject) (SignInResponseObject, error)
	// RefreshSession A longer session, from the refresh cookie
	// (POST /session/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// Tasks A page of the tasks that match, filtered and sorted by the server
	// (GET /tasks)
	Tasks(ctx context.Context, request TasksRequestObject) (TasksResponseObject, error)
	// CreateTask Make a task
	// (POST /tasks)
	CreateTask(ctx context.Context, request CreateTaskRequestObject) (CreateTaskResponseObject, error)
	// DeleteTask Delete a task
	// (DELETE /tasks/{id})
	DeleteTask(ctx context.Context, request DeleteTaskRequestObject) (DeleteTaskResponseObject, error)
	// Task One task
	// (GET /tasks/{id})
	Task(ctx context.Context, request TaskRequestObject) (TaskResponseObject, error)
	// UpdateTask Change a task; null takes a due day, a project or a file off
	// (PATCH /tasks/{id})
	UpdateTask(ctx context.Context, request UpdateTaskRequestObject) (UpdateTaskResponseObject, error)
	// Workspaces The workspaces the person belongs to
	// (GET /workspaces)
	Workspaces(ctx context.Context, request WorkspacesRequestObject) (WorkspacesResponseObject, error)
	// CreateWorkspace Make a workspace
	// (POST /workspaces)
	CreateWorkspace(ctx context.Context, request CreateWorkspaceRequestObject) (CreateWorkspaceResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

